import struct, zlib, glob
for f in sorted(glob.glob('input/*.png')):
    data=open(f,'rb').read()
    assert data[:8]==b'\x89PNG\r\n\x1a\n'
    pos=8; idat=b''; meta={}
    while pos<len(data):
        ln=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8].decode()
        chunk=data[pos+8:pos+8+ln]
        if typ=='IHDR':
            w,h,bd,ct=struct.unpack('>IIBB',chunk[:10]); meta['size']=(w,h,ct)
        if typ=='tEXt' or typ=='iTXt' or typ=='zTXt':
            meta.setdefault('texts',[]).append(chunk[:80])
        if typ=='PLTE':
            meta['palette']=list(chunk)
        if typ=='IHDR':
            meta['color']=ct
        pos+=12+ln
        if typ=='IEND': break
    print(f, meta.get('size'), meta.get('color'))
    pl=meta.get('palette')
    if pl: print(' palette len', len(pl)//3, pl[:24])
    if meta.get('texts'): print(' texts', meta['texts'][:5])
